"""Golden values generated by pinned upstream PR #12, not the implementation under test."""

import json
from datetime import datetime
from pathlib import Path

import pytest

from custom_components.ha_energy_price_engine.models import PriceSlot
from custom_components.ha_energy_price_engine.price_components import compose_dated
from custom_components.ha_energy_price_engine.price_engine import day_bounds
from custom_components.ha_energy_price_engine.tariff_source import (
    RADIUS_CODE,
    RADIUS_GLN,
    normalize_tariffs,
)

FIXTURES = Path(__file__).parent / "fixtures"
GOLDEN = json.loads((FIXTURES / "upstream_price_parity.json").read_text())
RADIUS = json.loads((FIXTURES / "radius_c_datahub.json").read_text())


@pytest.mark.parametrize(
    "scenario", GOLDEN["scenarios"], ids=lambda s: f"{s['day']}-{s['tariff']['mode']}"
)
def test_all_slots_match_original_upstream_final_prices(scenario):
    from datetime import date

    grid, provenance = normalize_tariffs(
        RADIUS, RADIUS_GLN, RADIUS_CODE, *day_bounds(date.fromisoformat(scenario["day"]))
    )
    assert provenance["version"] == scenario["radius_version"]
    for row in scenario["expected"]:
        slot = PriceSlot(
            datetime.fromisoformat(row["start"]), datetime.fromisoformat(row["end"]), row["raw"]
        )
        total, _ = compose_dated(slot, {**scenario["tariff"], "grid_slots": grid})
        assert total == pytest.approx(row["final"], abs=1e-12)
